        self.assertEqual(paginate(gen(six), 1, 3), ["m4", "m5", "m6"])
        self.assertEqual(paginate(gen(six), 2, 3), ["m1", "m2", "m3"])
        self.assertEqual(paginate(gen(six), 3, 3), [])

    def test_per_page_one_stream(self):
